function replaceMarkFields(PDO $db,array $payload): array{$field=(string)($payload['field']??'');if(!in_array($field,['city','trackName'],true))throw new ApiException('Indica si quieres reemplazar ciudad o pista.');$year=optionalYear($payload);if($field==='trackName'){$search=trim((string)($payload['search']??''));$replace=(string)($payload['replace']??'');if(trim($replace)==='')throw new ApiException('Indica el nombre de la pista.');$filters=[];$params=[];$area=(string)($payload['area']??'');if($area!==''){if(!in_array($area,EVENT_AREAS,true))throw new ApiException('Indica un ambito valido.');$filters[]='p.ambito = ?';$params[]=$area;}$cityId=filter_var($payload['cityId']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($cityId){ensureExists($db,'ciudades',(int)$cityId);$filters[]='m.ciudad_id = ?';$params[]=(int)$cityId;}if($year!==null){$filters[]='YEAR(m.fecha) = ?';$params[]=$year;}if($search===''&&$area===''&&!$cityId&&$year===null)throw new ApiException('Indica un texto a buscar, un ambito, una ciudad o un año para acotar el cambio.');if($search!==''){$set='m.nombre_pista = REPLACE(COALESCE(m.nombre_pista, ""), ?, ?)';array_unshift($params,$search,$replace);$filters[]='m.nombre_pista LIKE ?';$params[]='%'.$search.'%';}else{$set='m.nombre_pista = ?';array_unshift($params,$replace);}$where=$filters?' WHERE '.implode(' AND ',$filters):'';$statement=$db->prepare("UPDATE marcas m JOIN pruebas p ON p.id=m.prueba_id SET {$set}{$where}");$statement->execute($params);if($cityId&&$area!=='')upsertTrack($db,(int)$cityId,$area,$replace);return ['updated'=>$statement->rowCount()];}$search=requiredText($payload,'search','buscar');$replace=(string)($payload['replace']??'');$sourceId=filter_var($payload['searchCityId']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$targetId=filter_var($payload['replaceCityId']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($sourceId&&$targetId){ensureExists($db,'ciudades',(int)$sourceId);ensureExists($db,'c